export const reviewsTagged = (...tags: ReviewTag[]) => reviews.filter((r) => tags.some((t) => r.tags.includes(t)));
/** How many published reviews mention a theme, rounded down to a multiple of 5 for "20+" style claims. */
export const mentions = (tag: ReviewTag) => Math.floor(reviews.filter((r) => r.tags.includes(tag)).length / 5) * 5;
